// NPC普通拒绝回滚只触及过的共同值；覆盖多次删/插同一行动的原位置与边界顺序。
#include "resident/storage/common_checkpoint.hpp"
// 发布优化构建也必须执行本测试断言，不能让NDEBUG形成假绿。
#ifdef NDEBUG
#undef NDEBUG
#endif
#include <cassert>
#include <iostream>
using namespace hanmo::resident;
// typed字节核验额外覆盖不导出的字段序元数据，防止rollback悄悄改变检查点。
CodecVisitor::Buffer checkpoint(CommonState s){CodecVisitor::Buffer bytes;CodecVisitor c(bytes);assert(visit_common_checkpoint(c,s).ok&&c.finish().ok);return bytes;}
int main(){auto catalog=std::make_shared<CommonCatalog>();catalog->items.insert("grain",{"grain",1,1});CommonState seed;seed.next_instance_id=20;Owner owner{Owner::Kind::actor,"a",{}};ActorRecord person;person.id="a";person.fatigue=2;seed.actors.insert("a",person);seed.wallets.insert("wallet",{"wallet",owner,100,{}});seed.inventories.insert("i",{"i",owner,100,0,{{"lot:1","grain","",5,owner,{}}}});seed.inventories.insert("j",{"j",owner,100,0,{}});for(auto id:{"first","middle","last"}){seed.actions.insert(id,{id,"wait","a",{"a"},0,1});seed.action_field_order.insert(id,{"id","kind","actor_id","participants","remaining_ticks","start_tick","params"});}seed.roles.insert("role",{"a",true,{}});CommonStore store(seed,catalog);auto original=checkpoint(store.state());auto token=store.begin_savepoint();assert(token.ok&&!store.begin_savepoint().ok);ActorMutation actor;actor.actor_id="a";actor.fatigue=50;actor.location=WildernessLocation{"map","place",{1,2}};assert(store.apply_actor(actor).ok);ActionMutation change;change.kind=ActionMutation::Kind::erase;change.action.id="first";assert(store.apply_action(change).ok);change.action.id="middle";assert(store.apply_action(change).ok);change.kind=ActionMutation::Kind::insert;change.action={"first","travel","a",{"a"},0,3};assert(store.apply_action(change).ok);change.kind=ActionMutation::Kind::patch;change.action.id="last";change.remaining_ticks=8;assert(store.apply_action(change).ok);assert(store.apply_resources({{WalletDelta{"wallet",-9,true},TransferLots{"i","j","grain",2,{owner},{},{}},CreateWallet{{"new-wallet",owner,5,{}}},CreateInventory{{"new-inventory",owner,20,0,{}}}},{}}).ok);auto id=store.next_id("fact");assert(id.ok&&store.append_fact({id.value,"test","test"}).ok);assert(store.apply_role("role",{"a",false,{}}).ok);store.invalidate({ResourceKey::Kind::army,"army"});auto copy=store;auto child=copy.begin_savepoint();assert(child.ok&&child.value!=token.value);assert(copy.rollback_savepoint(child.value).ok);assert(store.rollback_savepoint(token.value).ok);assert(checkpoint(store.state())==original);assert(store.read_version({ResourceKey::Kind::actor,"a"}).version==0&&store.read_version({ResourceKey::Kind::army,"army"}).version==0);assert(!store.rollback_savepoint(token.value).ok);auto commit=store.begin_savepoint();assert(commit.ok);actor.fatigue=3;assert(store.apply_actor(actor).ok&&store.commit_savepoint(commit.value).ok);assert(store.actor("a")->fatigue==3&&!store.commit_savepoint(commit.value).ok);std::cout<<"state_savepoint: PASS (touched-only actor/action/resource/fact/role/ID/version undo, exact checkpoint order, token isolation)\n";}
